import type { MetadataRoute } from 'next'
import { connection } from 'next/server'
import { brandIconPalette, brandShortName } from '@/lib/brand-icon'
import { getBrand } from '@/lib/brand-server'

// Dynamic on purpose: the brand lives in the database (Settings > Branding), so this metadata route must render per request, never at build time.

// Web app manifest, named and coloured from the resolved brand (stored settings over BRAND_* env).
// The icon URLs are the ids generated by src/app/icon.tsx's generateImageMetadata.
export default async function manifest(): Promise<MetadataRoute.Manifest> {
  await connection()
  const b = await getBrand()
  const palette = brandIconPalette({ primaryColor: b.accent?.input ?? null })
  return {
    name: b.name,
    short_name: brandShortName(b.name),
    description: b.tagline,
    start_url: '/',
    display: 'standalone',
    background_color: palette.background,
    theme_color: palette.themeColorLight,
    icons: [
      { src: '/icon/192', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icon/512', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/icon/svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
      { src: '/apple-icon', sizes: '180x180', type: 'image/png', purpose: 'maskable' },
    ],
  }
}
